def _validate_request(data, request_id):
    """Validate the values required to handle an API request.

    The API expects a JSON object as its payload and a non-empty string as the
    request identifier.  Keep validation separate from request handling so
    invalid requests cannot be logged or processed accidentally.
    """
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    if not isinstance(request_id, str):
        raise TypeError("request_id must be a string")

    if not request_id.strip():
        raise ValueError("request_id must not be empty")


def handle_request(data, request_id):
    """Validate, log, and process an incoming API request."""
    _validate_request(data, request_id)
    audit_log(request_id, data)
    return process(data)

